import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import EventCard from "./events/EventCard";
import Chatbot from "./Chatbot";

export default function Home() {
  const [events, setEvents] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    fetch((process.env.REACT_APP_API || "http://localhost:4000") + "/api/dashboard/events")
      .then((res) => res.json())
      .then(setEvents)
      .catch(console.error);
  }, []);

  return (
    <div className="home-page">

      {/* HERO BANNER */}
      <section
        className="hero"
        style={{
          backgroundImage:
            "url('https://images.unsplash.com/photo-1488521787991-ed7bbaae773c?w=1350')",
          backgroundSize: "cover",
          backgroundPosition: "center",
          height: "80vh",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          color: "white",
          textShadow: "0 0 8px black",
          fontSize: "48px",
          fontWeight: "bold"
        }}
      >
        Making Communities Stronger Together
      </section>

      {/* ABOUT US */}
      <section className="section">
        <h2>About Us</h2>
        <p>
          HelpingHands is a non-profit organization working toward education,
          healthcare, women empowerment and social upliftment.
        </p>
      </section>

      {/* UPCOMING EVENTS */}
      <section className="section">
        <h2>Upcoming Events</h2>

        <div className="cards">
          {events.slice(0, 3).map((ev) => (
            <EventCard
              key={ev.id}
              event={ev}
              onClick={() => navigate(`/events/${ev.id}`)}
            />
          ))}
        </div>

        <button
          onClick={() => navigate("/events")}
          style={{
            marginTop: 20,
            padding: "10px 20px",
            background: "#0077cc",
            color: "white",
            border: "none",
            borderRadius: 6,
            cursor: "pointer",
          }}
        >
          View More Events →
        </button>
      </section>

      {/* CONTACT */}
      <section className="section">
        <h2>Contact Us</h2>
        <p><strong>Phone:</strong> +91 98765 43210</p>
        <p><strong>Email:</strong> support@ngoportal.org</p>
      </section>

      <Chatbot />
    </div>
  );
}
